async function p(c){const l=c.match(/<[^>]+>/g)||[],a=.2,o=l.filter(()=>Math.random()>a),t=l.filter(e=>!o.includes(e));let r=c;o.forEach(e=>{const s=e.replace(/^</,"").replace(/>$/,"");r=r.replaceAll(e,s)}),t.forEach(e=>{r=r.replaceAll(e,"")});const n=o.length*2+t.length*10;return await new Promise(e=>setTimeout(e,300+Math.random()*200)),{simulatedResponse:r.trim(),riskScore:n,droppedPlaceholders:t}}export{p as simulateLLM};
